373	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
374		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
375		logging.Info(logCtx, "turn-end",
376			slog.String("event", event.Type.String()),
377			slog.String("session_id", event.SessionID),
378			slog.String("session_ref", event.SessionRef),
379			slog.String("model", event.Model),
380		)
381	
382		sessionID := event.SessionID
383		if sessionID == "" {
384			sessionID = unknownSessionID
385		}
386	
387		// Fill model from hint file if the agent didn't provide it on this hook
388		if event.Model == "" && sessionID != unknownSessionID {
389			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
390				event.Model = hint
391				logging.Debug(logCtx, "loaded model from hint file",
392					slog.String("model", hint))
393			}
394		}
395	
396		transcriptRef := event.SessionRef
397		if transcriptRef == "" {
398			return errors.New("transcript file not specified")
399		}
400	
401		// If agent implements TranscriptPreparer, materialize the transcript file.
402		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
403		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
404		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
405		// TranscriptPreparer (Gemini, Droid) are unaffected.
406		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
407		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
408			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
409				logging.Warn(logCtx, "failed to prepare transcript",
410					slog.String("error", err.Error()))
411			}
412		}
413	
414		if !fileExists(transcriptRef) {
415			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
416			prepareSpan.End()
417			return fmt.Errorf("transcript file not found: %s", transcriptRef)
418		}
419	
420		// Early check: bail out quickly if the repo has no commits yet.

