 45	// handleSearchMemories handles the search_memories MCP tool call.
 46	func handleSearchMemories(ctx context.Context, request mcp.CallToolRequest) (*mcp.CallToolResult, error) {
 47		state, err := checkModeGate(ctx)
 48		if err != nil {
 49			return mcp.NewToolResultError(err.Error()), nil
 50		}
 51	
 52		query := request.GetString("query", "")
 53		kindFilter := request.GetString("kind", "")
 54		scopeFilter := request.GetString("scope", "")
 55		statusFilter := request.GetString("status", "active")
 56	
 57		records := state.Store.Records
 58	
 59		totalActive := countActive(records)
 60	
 61		var results []memoryResult
 62		if query != "" {
 63			results = scoreAndRank(query, records, statusFilter, kindFilter, scopeFilter)
 64		} else {
 65			results = filterAndSort(records, statusFilter, kindFilter, scopeFilter)
 66		}
 67	
 68		if len(results) > maxSearchResults {
 69			results = results[:maxSearchResults]
 70		}
 71	
 72		resp := searchResponse{
 73			Memories:    results,
 74			TotalActive: totalActive,
 75			Mode:        string(state.Store.Mode),
 76		}
