 78		data, err := json.Marshal(resp)
 79		if err != nil {
 80			return nil, fmt.Errorf("failed to marshal search response: %w", err)
 81		}
 82	
 83		return mcp.NewToolResultText(string(data)), nil
 84	}
 85	
 86	func countActive(records []memoryloop.MemoryRecord) int {
 87		count := 0
 88		for _, r := range records {
 89			if r.Status == memoryloop.StatusActive {
 90				count++
 91			}
 92		}
 93		return count
 94	}
 95	
 96	// tokenize splits text into lowercase tokens of 3+ chars, excluding stop words.
 97	func tokenize(text string) map[string]struct{} {
 98		tokens := make(map[string]struct{})
 99		words := strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
100			return 'a' > r || r > 'z'
101		})
102		for _, w := range words {
103			if len(w) < 3 {
104				continue
105			}
106			if _, isStop := searchStopWords[w]; isStop {
107				continue
108			}
109			tokens[w] = struct{}{}
110		}
111		return tokens
112	}
113	
114	// matchesFilters returns true if the record matches the given status/kind/scope filters.
115	func matchesFilters(r memoryloop.MemoryRecord, statusFilter, kindFilter, scopeFilter string) bool {
116		if statusFilter != "" && string(r.Status) != statusFilter {
117			return false
118		}
119		if kindFilter != "" && string(r.Kind) != kindFilter {
120			return false
121		}
122		if scopeFilter != "" && string(r.ScopeKind) != scopeFilter {
123			return false
124		}
125		return true
126	}
127	
128	func toMemoryResult(r memoryloop.MemoryRecord, score int) memoryResult {
129		return memoryResult{
130			ID:       r.ID,
131			Kind:     string(r.Kind),
132			Title:    r.Title,
133			Body:     r.Body,
134			Why:      r.Why,
135			Strength: r.Strength,
136			Scope:    string(r.ScopeKind),
137			Outcome:  string(r.Outcome),
138			Score:    score,
139		}
140	}
141	
142	// scoreAndRank scores records by token overlap with query, applies filters, and returns sorted results.
143	func scoreAndRank(query string, records []memoryloop.MemoryRecord, statusFilter, kindFilter, scopeFilter string) []memoryResult {
144		queryTokens := tokenize(query)
145	
146		type scored struct {
147			result   memoryResult
148			score    int
149			strength int
150		}
151	
152		var candidates []scored
153		for _, r := range records {
154			if !matchesFilters(r, statusFilter, kindFilter, scopeFilter) {
155				continue
156			}
157			recordTokens := tokenize(r.Title + " " + r.Body)
158			overlap := 0
159			for t := range queryTokens {
160				if _, ok := recordTokens[t]; ok {
161					overlap++
162				}
163			}
164			candidates = append(candidates, scored{
165				result:   toMemoryResult(r, overlap),
166				score:    overlap,
167				strength: r.Strength,
168			})
169		}
170	
171		sort.SliceStable(candidates, func(i, j int) bool {
172			if candidates[i].score != candidates[j].score {
173				return candidates[i].score > candidates[j].score
174			}
175			return candidates[i].strength > candidates[j].strength
176		})
177	
178		results := make([]memoryResult, 0, len(candidates))
179		for _, c := range candidates {
180			results = append(results, c.result)
181		}
182		return results
183	}
184	
185	// filterAndSort filters records by status/kind/scope and sorts by strength desc then title asc.
186	func filterAndSort(records []memoryloop.MemoryRecord, statusFilter, kindFilter, scopeFilter string) []memoryResult {
187		var filtered []memoryloop.MemoryRecord
188		for _, r := range records {
189			if matchesFilters(r, statusFilter, kindFilter, scopeFilter) {
190				filtered = append(filtered, r)
191			}
192		}
193	
194		sort.SliceStable(filtered, func(i, j int) bool {
195			if filtered[i].Strength != filtered[j].Strength {
196				return filtered[i].Strength > filtered[j].Strength
197			}
198			return filtered[i].Title < filtered[j].Title
199		})
200	
201		results := make([]memoryResult, 0, len(filtered))
202		for _, r := range filtered {
203			results = append(results, toMemoryResult(r, 0))
204		}
205		return results
206	}

