// --- MCP Server tests ---

func readProjectMCPServers(t *testing.T, tempDir string) map[string]json.RawMessage {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(tempDir, ".mcp.json"))
	if err != nil {
		t.Fatalf("read .mcp.json: %v", err)
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		t.Fatalf("parse .mcp.json: %v", err)
	}
	mcpRaw, ok := raw["mcpServers"]
	if !ok {
		return nil
	}
	var mcpServers map[string]json.RawMessage
	if err := json.Unmarshal(mcpRaw, &mcpServers); err != nil {
		t.Fatalf("parse mcpServers: %v", err)
	}
	return mcpServers
}

func writeProjectMCPFile(t *testing.T, tempDir, content string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(tempDir, ".mcp.json"), []byte(content), 0o644); err != nil {
		t.Fatalf("failed to write .mcp.json: %v", err)
	}
}

func TestInstallHooks_WritesProjectMCPServerEntry(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &ClaudeCodeAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	mcpServers := readProjectMCPServers(t, tempDir)
	if mcpServers == nil {
		t.Fatal("mcpServers not found in .mcp.json")
	}

	entireRaw, ok := mcpServers["entire"]
	if !ok {
		t.Fatal("mcpServers.entire not found")
	}

	var config mcpServerEntry
	if err := json.Unmarshal(entireRaw, &config); err != nil {
		t.Fatalf("parse entire config: %v", err)
	}
	if config.Command != "entire" {
		t.Errorf("command = %s, want entire", config.Command)
	}
	if len(config.Args) != 1 || config.Args[0] != "mcp-server" {
		t.Errorf("args = %v, want [mcp-server]", config.Args)
	}

	settingsPath := filepath.Join(tempDir, ".claude", "settings.json")
	data, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Fatalf("read settings: %v", err)
	}
	var rawSettings map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawSettings); err != nil {
		t.Fatalf("parse settings: %v", err)
	}
	if _, ok := rawSettings["mcpServers"]; ok {
		t.Fatal("mcpServers should not be written to .claude/settings.json")
	}
}

func TestInstallHooks_MCPServerLocalDev(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)
	t.Setenv("CLAUDE_PROJECT_DIR", "/dev/cli")

	ag := &ClaudeCodeAgent{}
	_, err := ag.InstallHooks(context.Background(), true, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	mcpServers := readProjectMCPServers(t, tempDir)
	entireRaw := mcpServers["entire"]

	var config mcpServerEntry
	if err := json.Unmarshal(entireRaw, &config); err != nil {
		t.Fatalf("parse: %v", err)
	}
	if config.Command != "go" {
		t.Errorf("command = %s, want go", config.Command)
	}
	if len(config.Args) < 3 || config.Args[len(config.Args)-1] != "mcp-server" {
		t.Errorf("args = %v, want [..., mcp-server]", config.Args)
	}
}

func TestUninstallHooks_RemovesMCPServerEntry(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &ClaudeCodeAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	if err := ag.UninstallHooks(context.Background()); err != nil {
		t.Fatalf("UninstallHooks() error = %v", err)
	}

	mcpServers := readProjectMCPServers(t, tempDir)
	if mcpServers != nil {
		if _, ok := mcpServers["entire"]; ok {
			t.Error("mcpServers.entire should be removed after uninstall")
		}
	}
}

func TestInstallHooks_PreservesExistingMCPServers(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	writeProjectMCPFile(t, tempDir, `{
		"mcpServers": {
			"other-tool": {
				"command": "other-mcp",
				"args": ["serve"]
			}
		}
	}`)

	ag := &ClaudeCodeAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	mcpServers := readProjectMCPServers(t, tempDir)
	if _, ok := mcpServers["entire"]; !ok {
		t.Error("mcpServers.entire not found")
	}
	if _, ok := mcpServers["other-tool"]; !ok {
		t.Error("mcpServers.other-tool was not preserved")
	}
}

func TestInstallHooks_RemovesLegacySettingsMCPServerEntry(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	writeSettingsFile(t, tempDir, `{
		"mcpServers": {
			"entire": {
				"command": "/tmp/entire",
				"args": ["mcp-server"]
			},
			"other-tool": {
				"command": "other-mcp",
				"args": ["serve"]
			}
		}
	}`)

	ag := &ClaudeCodeAgent{}
	_, err := ag.InstallHooks(context.Background(), false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	data, err := os.ReadFile(filepath.Join(tempDir, ".claude", "settings.json"))
	if err != nil {
		t.Fatalf("read settings: %v", err)
	}
	var rawSettings map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawSettings); err != nil {
		t.Fatalf("parse settings: %v", err)
	}
	var settingsMCP map[string]json.RawMessage
	if raw, ok := rawSettings["mcpServers"]; ok {
		if err := json.Unmarshal(raw, &settingsMCP); err != nil {
			t.Fatalf("parse legacy mcpServers: %v", err)
		}
	}
	if _, ok := settingsMCP["entire"]; ok {
		t.Fatal("legacy .claude/settings.json mcpServers.entire should be removed")
	}
	if _, ok := settingsMCP["other-tool"]; !ok {
		t.Fatal("legacy .claude/settings.json should preserve non-Entire mcp entries")
